### 2. `Script.js` 纯动态脚本标准模板 (<80 行)
```javascript
// ============================================================================
// Clash Verge Rev 全局扩展脚本 (Global Extension Script)
// 职责边界：仅保留必须根据运行时数据动态计算的逻辑（< 80 行纯动态代码）
// 1. 动态裁撤机场虚假同质化克隆分组，规则归一收拢至主组
// 2. 动态提取前 10 个可用代理节点，绑定本地独立端口监听 (17001 ~ 17010)
// ============================================================================

function main(config, profileName) {
  if (!config) return {};

  // 1. 动态匹配主代理组
  const groups = config["proxy-groups"] || [];
  let proxyName = "节点选择";
  const preferredGroups = [
    "节点选择", "Proxy", "PROXY", "代理", "GLOBAL", "Global", "🚀 节点选择"
  ];

  let mainGroup = groups.find((g) => preferredGroups.includes(g.name));
  if (!mainGroup) {
    mainGroup = groups.find(
      (g) => g.type === "select" && Array.isArray(g.proxies) && g.proxies.length > 0
    );
  }
  if (!mainGroup) {
    mainGroup = groups.find(
      (g) => Array.isArray(g.proxies) && g.proxies.length > 0
    );
  }
  if (mainGroup) proxyName = mainGroup.name;

  // 2. 裁撤同质化虚假克隆分组，规则动态收拢
  const redundantKeywords = [
    "Youtube", "Telegram", "奈飞", "OpenAi", "Steam", "Emby", "Microsoft", "Crypto"
  ];

  if (Array.isArray(config.rules)) {
    config.rules = config.rules.map((rule) => {
      const parts = rule.split(",");
      if (parts.length >= 3) {
        const target = parts[2].trim();
        if (target.includes("Steam") || target.includes("Microsoft") || target.includes("Crypto")) {
          parts[2] = "DIRECT";
          return parts.join(",");
        }
        for (const kw of redundantKeywords) {
          if (target.includes(kw)) {
            parts[2] = proxyName;
            return parts.join(",");
          }
        }
      }
      return rule;
    });
  }

  if (Array.isArray(config["proxy-groups"])) {
    config["proxy-groups"] = config["proxy-groups"].filter((g) => {
      return !redundantKeywords.some((kw) => g.name.includes(kw));
    });
  }

  // 3. 动态映射多节点独立端口监听 (17001 ~ 17010)
  const excludeKeywords = [
    "自动选择", "故障转移", "fallback", "auto", "DIRECT", "REJECT",
    "剩余流量", "流量", "到期", "重置"
  ];

  let candidateNames = [];
  if (mainGroup && Array.isArray(mainGroup.proxies)) {
    candidateNames = mainGroup.proxies;
  } else {
    candidateNames = (config.proxies || []).map((p) => p.name);
  }

  const realProxies = candidateNames.filter((name) => {
    if (!name) return false;
    const lower = name.toLowerCase();
    for (const keyword of excludeKeywords) {
      if (lower.includes(keyword.toLowerCase())) return false;
    }
    return true;
  });

  config.listeners = (config.listeners || []).filter(
    (l) => !(l.name && l.name.startsWith("qwen-node-"))
  );
  const maxPorts = 10;
  realProxies.slice(0, maxPorts).forEach((proxy, index) => {
    config.listeners.push({
      name: `qwen-node-${index + 1}`,
      type: "mixed",
      port: 17001 + index,
      proxy: proxy,
    });
  });

  return config;
}
```

